const unsigned char rcon[11] = {
    0x00, 0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36};

inline unsigned char xtime(unsigned char x) {
    unsigned char hibit = static_cast<unsigned char>(x & 0x80);
    unsigned char shifted = static_cast<unsigned char>(x << 1);
    if (hibit) {
        shifted = static_cast<unsigned char>(shifted ^ 0x1b);
    }
    return shifted;
}

inline unsigned char gmul(unsigned char a, unsigned char b) {
    unsigned char p = 0;
    for (int i = 0; i < 8; ++i) {
        if (b & 1) {
            p ^= a;
        }
        bool hi = (a & 0x80) != 0;
        a = static_cast<unsigned char>(a << 1);
        if (hi) {
            a = static_cast<unsigned char>(a ^ 0x1b);
        }
        b >>= 1;
    }
    return p;
}

void key_expansion(const unsigned char key[16], unsigned char round_keys[176]) {
    for (int i = 0; i < 16; ++i) {
        round_keys[i] = key[i];
    }

    unsigned char temp[4];
    int bytes_generated = 16;
    int rcon_idx = 1;

    while (bytes_generated < 176) {
        for (int i = 0; i < 4; ++i) {
            temp[i] = round_keys[bytes_generated - 4 + i];
        }

        if (bytes_generated % 16 == 0) {
            unsigned char t0 = temp[0];
            temp[0] = static_cast<unsigned char>(sbox[temp[1]] ^ rcon[rcon_idx]);
            temp[1] = sbox[temp[2]];
            temp[2] = sbox[temp[3]];
            temp[3] = sbox[t0];
            rcon_idx++;
        }

        for (int i = 0; i < 4; ++i) {
            round_keys[bytes_generated] =
                static_cast<unsigned char>(round_keys[bytes_generated - 16] ^ temp[i]);
            bytes_generated++;
        }
    }
}

void add_round_key(unsigned char state[16], const unsigned char round_key[16]) {
    for (int i = 0; i < 16; ++i) {
        state[i] = static_cast<unsigned char>(state[i] ^ round_key[i]);
    }
}

void sub_bytes(unsigned char state[16]) {
    for (int i = 0; i < 16; ++i) {
        state[i] = sbox[state[i]];
    }
}

void shift_rows(unsigned char state[16]) {
    unsigned char tmp;

    tmp = state[1];
    state[1] = state[5];
    state[5] = state[9];
    state[9] = state[13];
    state[13] = tmp;

    tmp = state[2];
    unsigned char tmp2 = state[6];
    state[2] = state[10];
    state[6] = state[14];
    state[10] = tmp;
    state[14] = tmp2;

    tmp = state[15];
    state[15] = state[11];
    state[11] = state[7];
    state[7] = state[3];
    state[3] = tmp;
}

void mix_columns(unsigned char state[16]) {
    for (int c = 0; c < 4; ++c) {
        unsigned char a0 = state[c * 4 + 0];
        unsigned char a1 = state[c * 4 + 1];
        unsigned char a2 = state[c * 4 + 2];
        unsigned char a3 = state[c * 4 + 3];

        state[c * 4 + 0] = static_cast<unsigned char>(gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3);
        state[c * 4 + 1] = static_cast<unsigned char>(a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3);
        state[c * 4 + 2] = static_cast<unsigned char>(a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3));
        state[c * 4 + 3] = static_cast<unsigned char>(gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2));
    }
}

}  // namespace

void encrypt_block(const unsigned char key[16],
                    const unsigned char plaintext[16],
                    unsigned char ciphertext[16]) {
    unsigned char round_keys[176];

    key_expansion(key, round_keys);

    unsigned char state[16];
    for (int i = 0; i < 16; ++i) {
        state[i] = plaintext[i];
    }

    add_round_key(state, &round_keys[0]);

    for (int round = 1; round <= 9; ++round) {
        sub_bytes(state);
        shift_rows(state);
        mix_columns(state);
        add_round_key(state, &round_keys[round * 16]);
    }

    sub_bytes(state);
    shift_rows(state);
    add_round_key(state, &round_keys[10 * 16]);

    for (int i = 0; i < 16; ++i) {
        ciphertext[i] = state[i];
    }

    return;
}
